38	/****************************************************************************
39	 * Private Definitions
40	 ****************************************************************************/
41	
42	#define LD2410B_DEV           "/dev/ttyS0"
43	#define LD2410B_BAUD          B115200
44	
45	/* 帧头/帧尾 */
46	#define FRAME_HDR0            0xF4
47	#define FRAME_HDR1            0xF3
48	#define FRAME_HDR2            0xF2
49	#define FRAME_HDR3            0xF1
50	#define FRAME_TAIL0           0xF8
51	#define FRAME_TAIL1           0xF7
52	#define FRAME_TAIL2           0xF6
53	#define FRAME_TAIL3           0xF5
54	
55	#define DATA_TYPE_BASIC       0x02   /* 目标基本信息数据 */
56	#define DATA_HEAD_AA          0xAA
57	#define DATA_TAIL_55          0x55
58	
59	/* 数据区字段偏移（数据区起点 = type 字节） */
60	#define OFF_STATE      2   /* 目标状态 1B */
61	#define OFF_MOVE_DIST  3   /* 运动距离 2B LE */
62	#define OFF_STAT_DIST  6   /* 静止距离 2B LE */
63	#define OFF_DET_DIST   9   /* 探测距离 2B LE */
64	#define DATA_LEN_BASIC 13  /* type..0x00 共 13B（len 字段值 = 0x0D） */
65	
66	/* 帧状态机 */
67	enum
68	{
69	  ST_WAIT_HDR = 0,  /* 等 F4 */
70	  ST_HDR1,          /* 等 F3 */
71	  ST_HDR2,          /* 等 F2 */
72	  ST_HDR3,          /* 等 F1 */
73	  ST_LEN_LO,        /* 等 len 低字节 */
74	  ST_LEN_HI,        /* 等 len 高字节 */
75	  ST_DATA,          /* 收帧内数据 len 字节 */
76	  ST_TAIL0,         /* 等 F8 */
77	  ST_TAIL1,         /* 等 F7 */
78	  ST_TAIL2,         /* 等 F6 */
79	  ST_TAIL3,         /* 等 F5（收齐 = 一帧完成） */
80	};
81	
82	#define FRAME_MAX_LEN         128   /* 工程模式帧 < 64B，留余量 */
83	
84	/****************************************************************************
85	 * Private Data
86	 ****************************************************************************/
87	
88	static pthread_t       g_ld2410b_thread;
89	static volatile bool   g_ld2410b_run;      /* 线程运行标志 */
90	static volatile bool   g_ld2410b_ready;    /* 串口已打开 */
91	static volatile int    g_ld2410b_state;    /* 最近一帧目标状态 */
92	static volatile int    g_ld2410b_dist_cm;  /* 最近一帧探测距离 */
93	static volatile bool   g_ld2410b_frame_ok; /* 已成功解析过完整帧 */
94	static volatile int    g_ld2410b_last_ts;  /* 最近一帧到达时刻（lv_tick ms，WARN3 帧过期用） */
95	
96	/****************************************************************************
97	 * Private Functions
98	 ****************************************************************************/
99	
100	/* 提取小端 2B 值 */
101	static int ld2410b_le16(const uint8_t *p)
102	{
103	  return (int)(p[0] | (p[1] << 8));
104	}
105	
106	/* 校验并解析一帧数据区（d 指向 type 字节，len = 数据区长度）
107	 * 成功更新 g_ld2410b_state / g_ld2410b_dist_cm 并返回 0 */
108	static int ld2410b_parse_frame(const uint8_t *d, int len)
109	{
110	  if (len < DATA_LEN_BASIC)
111	    return -1;
112	  if (d[0] != DATA_TYPE_BASIC || d[1] != DATA_HEAD_AA)
113	    return -1;                       /* 非目标基本信息帧 */
114	  if (d[OFF_STATE] > 0x03)
115	    return -1;                       /* 状态值非法（底噪检测等不理会） */
116	  if (d[11] != DATA_TAIL_55 || d[12] != 0x00)
117	    return -1;                       /* 数据区尾部校验失败 */
118	
119	  g_ld2410b_state   = d[OFF_STATE];
120	  g_ld2410b_dist_cm = ld2410b_le16(&d[OFF_DET_DIST]);
121	  g_ld2410b_frame_ok = true;
122	  g_ld2410b_last_ts = lv_tick_get();   /* WARN3：记录帧到达时刻供过期判断 */
123	  return 0;
124	}
125	
126	/* 串口读取线程：poll → read → 状态机 → 提取目标状态/距离
127	 * 2026-08-23 审查修复（FAIL1）：O_NONBLOCK 直 read 无数据时忙转烧 CPU，
128	 * 改 poll(POLLIN, 200ms) 带超时等待——无数据时线程休眠，不空转。 */
129	static void *ld2410b_reader(void *arg)
130	{
131	  int      fd = (int)(intptr_t)arg;
132	  uint8_t  buf[64];
133	  uint8_t  frame[FRAME_MAX_LEN];
134	  int      fpos = 0;
135	  int      flen = 0;
136	  int      st   = ST_WAIT_HDR;
137	  struct pollfd pfd;
138	
139	  pfd.fd     = fd;
140	  pfd.events = POLLIN;
141	
142	  while (g_ld2410b_run)
143	    {
144	      int pr = poll(&pfd, 1, 200);
145	      if (pr <= 0)
146	        continue;                    /* 超时/无数据：正常休眠重试 */
147	
148	      ssize_t n = read(fd, buf, sizeof(buf));
149	      if (n <= 0)
150	        continue;                    /* 无数据可读（非阻塞，直接重试） */
151	
152	      for (ssize_t i = 0; i < n; i++)
153	        {
154	          uint8_t b = buf[i];
155	
156	          switch (st)
157	            {
158	            case ST_WAIT_HDR:
159	              if (b == FRAME_HDR0) st = ST_HDR1;
160	              break;
161	            case ST_HDR1:
162	              st = (b == FRAME_HDR1) ? ST_HDR2 : ST_WAIT_HDR;
163	              break;
164	            case ST_HDR2:
165	              st = (b == FRAME_HDR2) ? ST_HDR3 : ST_WAIT_HDR;
166	              break;
167	            case ST_HDR3:
168	              st = (b == FRAME_HDR3) ? ST_LEN_LO : ST_WAIT_HDR;
169	              break;
170	            case ST_LEN_LO:
171	              flen = b;
172	              st   = ST_LEN_HI;
173	              break;
174	            case ST_LEN_HI:
175	              flen |= (b << 8);
176	              if (flen < DATA_LEN_BASIC || flen > FRAME_MAX_LEN)
177	                {
178	                  st = ST_WAIT_HDR;  /* 长度非法，重新找头 */
179	                }
180	              else
181	                {
182	                  fpos = 0;
183	                  st   = ST_DATA;
184	                }
185	              break;
186	            case ST_DATA:
187	              frame[fpos++] = b;
188	              if (fpos >= flen)
189	                st = ST_TAIL0;
190	              break;
191	            case ST_TAIL0:
192	              st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_WAIT_HDR;
193	              break;
194	            case ST_TAIL1:
195	              st = (b == FRAME_TAIL1) ? ST_TAIL2 : ST_WAIT_HDR;
196	              break;
197	            case ST_TAIL2:
198	              st = (b == FRAME_TAIL2) ? ST_TAIL3 : ST_WAIT_HDR;
199	              break;
200	            case ST_TAIL3:
201	              if (b == FRAME_TAIL3)
202	                {
203	                  ld2410b_parse_frame(frame, flen);   /* 一帧收齐 */
204	                }
205	              st = ST_WAIT_HDR;
206	              break;
207	            default:
208	              st = ST_WAIT_HDR;
209	              break;
210	            }
211	        }
212	    }
213	
214	  close(fd);
215	  return NULL;
216	}
