218	/****************************************************************************
219	 * Public Functions
220	 ****************************************************************************/
221	
222	int dm_ld2410b_init(void)
223	{
224	  struct termios tio;
225	  int fd;
226	
227	  if (g_ld2410b_ready)
228	    return 0;                        /* 已初始化 */
229	
230	  fd = open(LD2410B_DEV, O_RDONLY | O_NONBLOCK);
231	  if (fd < 0)
232	    {
233	      LV_LOG_ERROR("[ld2410b] open %s failed: %d", LD2410B_DEV, errno);
234	      return -1;
235	    }
236	
237	  /* 115200 8N1，raw 模式 */
238	  memset(&tio, 0, sizeof(tio));
239	  if (tcgetattr(fd, &tio) < 0)
240	    {
241	      close(fd);
242	      return -1;
243	    }
244	  cfmakeraw(&tio);
245	  cfsetispeed(&tio, LD2410B_BAUD);
246	  cfsetospeed(&tio, LD2410B_BAUD);
247	  tio.c_cflag |= (CLOCAL | CREAD);
248	  if (tcsetattr(fd, TCSANOW, &tio) < 0)
249	    {
250	      close(fd);
251	      return -1;
252	    }
253	
254	  g_ld2410b_run = true;
255	  if (pthread_create(&g_ld2410b_thread, NULL, ld2410b_reader,
256	                     (void *)(intptr_t)fd) != 0)
257	    {
258	      close(fd);
259	      g_ld2410b_run = false;
260	      return -1;
261	    }
262	
263	  g_ld2410b_ready = true;
264	  LV_LOG_INFO("[ld2410b] init ok (%s @115200)", LD2410B_DEV);
265	  return 0;
266	}
267	
