/****************************************************************************
 * Name: set_format_and_baudrate
 *
 * Description:
 *   Configure the UART baud, bits, parity, etc. This method is
 *   called the first time that the serial port is opened.
 *
 ****************************************************************************/
static void set_format_and_baudrate(struct uart_dev_s *dev)
{
#ifndef CONFIG_SUPPRESS_UART_CONFIG
  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
  uint16_t dl;
  uint32_t lcr;
  /* Set up the LCR */

  lcr = 0;

  switch (priv->bits)
    {
    case 5:
      lcr |= UART_LCR_DLS_5BITS;
      break;

    case 6:
      lcr |= UART_LCR_DLS_6BITS;
      break;

    case 7:
      lcr |= UART_LCR_DLS_7BITS;
      break;

    case 8:
    default:
      lcr |= UART_LCR_DLS_8BITS;
      break;
    }

  if (priv->stopbits2)
    {
      lcr |= UART_LCR_STOP;
    }

  if (priv->parity == 1)
    {
      lcr |= UART_LCR_PEN;
      lcr &= ~UART_LCR_EPS;
    }
  else if (priv->parity == 2)
    {
      lcr |= (UART_LCR_PEN | UART_LCR_EPS);
    }
  else if (priv->parity == 0)
    {
      lcr &= ~UART_LCR_PEN;
    }


  dl = r528_uartdl(priv->baud);

  arm_serialout(priv, R528_UART_HALT_OFFSET, UART_HALT_HALT_TX | UART_HALT_FORCECFG);
  /* Enter DLAB=1 */

  arm_serialout(priv, R528_UART_LCR_OFFSET, (lcr | UART_LCR_DLAB));

  /* Set the BAUD divisor */
  arm_serialout(priv, R528_UART_DLH_OFFSET, dl >> 8);
  arm_serialout(priv, R528_UART_DLL_OFFSET, dl & 0xff);

}

/****************************************************************************
 * dm_health.c 调用：人体感应距离 cm
 * 2026-08-23：数据源从 LTR553 接近传感器切换为 LD2410B 毫米波雷达。
 *   - 有人（状态≠NONE）且 探测距离 ≤ ld2410_seat_cm（默认 200cm）→ 返回 0
 *     （≤30cm 判据通过 = 在座）
 *   - 有人但超出阈值 / 无人 → 返回 99（>30cm 判据 = 离开）
 *   - LD2410B 串口不可用 → -1（dm_health 回退纯计时模式）
 ****************************************************************************/
int dm_prox_get_cm(void)
{
    int present = dm_ld2410b_present();
    int dist;

    if (present < 0)
        return -1;       /* 串口未就绪：回退纯计时 */
    if (present == 0)
        return 99;       /* 无人：离开 */

    dist = dm_ld2410b_get_dist_cm();
    if (dist >= 0 && dist <= LD2410B_SEAT_CM_DEFAULT)
        return 0;        /* 有人且在座距离内：在座 */
    return 99;           /* 有人但超出阈值 / 距离未知：离开 */
}

