126	/* 串口读取线程：poll → read → 状态机 → 提取目标状态/距离
127	 * 2026-08-23 审查修复（FAIL1）：O_NONBLOCK 直 read 无数据时忙转烧 CPU，
128	 * 改 poll(POLLIN, 200ms) 带超时等待——无数据时线程休眠，不空转。 */
129	static void *ld2410b_reader(void *arg)
130	{
131	  int      fd = (int)(intptr_t)arg;
132	  uint8_t  buf[64];
133	  uint8_t  frame[FRAME_MAX_LEN];
134	  int      fpos = 0;
135	  int      flen = 0;
136	  int      st   = ST_WAIT_HDR;
137	  struct pollfd pfd;
138	
139	  pfd.fd     = fd;
140	  pfd.events = POLLIN;
141	
142	  while (g_ld2410b_run)
143	    {
144	      int pr = poll(&pfd, 1, 200);
145	      if (pr <= 0)
146	        continue;                    /* 超时/无数据：正常休眠重试 */
147	
148	      ssize_t n = read(fd, buf, sizeof(buf));
149	      if (n <= 0)
150	        continue;                    /* 无数据可读（非阻塞，直接重试） */
151	
152	      for (ssize_t i = 0; i < n; i++)
153	        {
154	          uint8_t b = buf[i];
155	
156	          switch (st)
157	            {
158	            case ST_WAIT_HDR:
159	              if (b == FRAME_HDR0) st = ST_HDR1;
160	              break;
161	            case ST_HDR1:
162	              st = (b == FRAME_HDR1) ? ST_HDR2 : ST_WAIT_HDR;
163	              break;
164	            case ST_HDR2:
165	              st = (b == FRAME_HDR2) ? ST_HDR3 : ST_WAIT_HDR;
166	              break;
167	            case ST_HDR3:
168	              st = (b == FRAME_HDR3) ? ST_LEN_LO : ST_WAIT_HDR;
169	              break;
170	            case ST_LEN_LO:
171	              flen = b;
172	              st   = ST_LEN_HI;
173	              break;
174	            case ST_LEN_HI:
175	              flen |= (b << 8);
176	              if (flen < DATA_LEN_BASIC || flen > FRAME_MAX_LEN)
177	                {
178	                  st = ST_WAIT_HDR;  /* 长度非法，重新找头 */
179	                }
180	              else
181	                {
182	                  fpos = 0;
183	                  st   = ST_DATA;
184	                }
185	              break;
186	            case ST_DATA:
187	              frame[fpos++] = b;
188	              if (fpos >= flen)
189	                st = ST_TAIL0;
190	              break;
191	            case ST_TAIL0:
192	              st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_WAIT_HDR;
193	              break;
194	            case ST_TAIL1:
195	              st = (b == FRAME_TAIL1) ? ST_TAIL2 : ST_WAIT_HDR;
196	              break;
197	            case ST_TAIL2:
198	              st = (b == FRAME_TAIL2) ? ST_TAIL3 : ST_WAIT_HDR;
199	              break;
200	            case ST_TAIL3:
201	              if (b == FRAME_TAIL3)
202	                {
203	                  ld2410b_parse_frame(frame, flen);   /* 一帧收齐 */
204	                }
205	              st = ST_WAIT_HDR;
206	              break;
207	            default:
208	              st = ST_WAIT_HDR;
209	              break;
210	            }
211	        }
212	    }
213	
214	  close(fd);
215	  return NULL;
216	}
